在复杂的网页应用中，DOM 结构会频繁的发生变化，有的时候我们需要根据变化来进行相应的操作，以往通过 Mutation Events 来监听 DOM 的变化，目前它已经废弃了，被 MutationObserver 所取代。 MutationObserver 的兼容性很好，可以放心大胆的使用。 基本用法 MutationObserver 的基本用法如下 const observer = new MutationObserver(mutations => { }); observer.observe(element, options); 我们通过 new MutationObserver() 创建一个 MutationObserver 对象，构造函数接收一个回调函数作为参数，当被监听的元素 DOM 发生变化时，该回调函数将会执行。 回调函数接收一个参数，该参数是一个数组，其中元素类型为 MutationRecord ， MutationRecord 包含如下属性： { type: 'attributes', target: div#container, addedNodes: [], removeNodes: [], previousSibling: null, nextSibling: null, attributeName: '', attributeNamespace: null, oldValue: '' } 在后续内容中会详细介绍每个字段的作用。 通过 observe(element, options) 对元素 element 进行监听，除了需要传入要监听的元素以外，还需要传递一个 options 对象，它包括如下字段： { childList: true, attributes: true, attributeFilter: ['class', 'style'], attributeOldValue: true, characterData: true, characterDataOldValue: true, subtree: true } 这里为了完整性将可设置的所有参数列了出来，实际在 options 参数并不需要指定每一个属性。 可以观察到除了 attributeFilter 属性外，其它属性都是布尔值，也就说这些属性相当于一个开关，设置某个属性为 true 就相当于开启某个特性，后面会详细介绍每个属性的作用。 :::note{ title=注意} 虽然不需要指定每一个属性，但是 childList , attributes , characterData 这三个属性必须有一个设置为 true 。 ::: 如果不再需要监听 DOM 的变化时，可以通过 observer.disconnect() 方法停止监听。 来看一个🌰。 :::tau-node{type="tabs"} {"type":"tabs","tauContract":"0256f72bf503014a7ea32d073aa02da06da7e88c98797870e4d49fa627404693","collabId":"18842dce-b1e2-461e-8287-9f06ba5f6cf9","children":[{"type":"tab-pane","tabKey":"db8c6a46-2ded-4dbb-81d0-78225a9fa894","title":"HTML","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"6ec54172-a9b1-4a28-b487-c93440554ad5","children":[{"type":"code-block","language":"html","uuid":"8d020015-620e-4822-afdd-e22bf914a81a","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"29dbd91b-b812-467c-9174-2b8c3097fc01","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"<div id="container">
 <p>世界这么大，我想去看看</p>
</div>
<button id="btn">删除元素</button>","collabId":"1ce173f1-1796-4763-9c35-f0cc2ff41b3e","children":[{"type":"formatted","text":""}]}]}]},{"type":"tab-pane","tabKey":"d2a16188-899a-448b-8959-0dc7624d098d","title":"JavaScript","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"930673f0-eb8a-4eb8-8e99-99d192539eec","children":[{"type":"code-block","language":"js","uuid":"2d1ae2e2-e9af-41e2-86df-09c037cf2fe9","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"68411d5f-2cc5-415e-a380-8ad2319e35a6","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"const observer = new MutationObserver(mutations => {
 console.log(mutations);
});
observer.observe(document.getElementById('container'), {
 childList: true
});

const btn = document.getElementById('btn');
btn.addEventListener('click', () => {
 document.getElementById('container').removeChild(
 document.querySelector('#container p')
 );
});","collabId":"7b31266e-3d71-493b-abae-2d2895a04e04","children":[{"type":"formatted","text":""}]}]}]}]} ::: 页面中有一个 id 为 container 的元素，其中有一个 p 标签， p 标签中其中包含一些文字。页面中还有一个按钮，当点击按钮时，会将 p 标签从 container 中移除。 现在我们创建一个 MutationObserver ，并监听了 container 元素，设置 options 中的 childList 为 true ，表示当 container 的子节点发生变化时（新增或删除），将会被监听到，从而触发回调函数的执行。在回调函数中，我们只是简单的打印了回调函数的参数。 可以观察到，当我们删除 p 标签时，控制台打印了内容，表示 container 的变化被监听到了。 :::info{ title=信息} 通过 MutationObserver 可以监视到三种 DOM 变化： 子元素发生变化（新增或删除） 属性发生变化 包含的文本发生变化 可通过 MutationRecord 对象的 type 属性来区分是何种变化，它有三个值分别与上述变化对应： childList attributes characterData ::: 通过 childList 来监听子元素的变化 childList 当 options 中的 childList 设置为 true 时，表示监听子元素的变化，即子元素的新增与删除。 同样在页面上存在一个 container 元素，其中包含了一个 p 标签；页面上同时存在一个按钮，当点击按钮时会删除 p 标签或者创建 p 标签。 :::tau-node{type="tabs"} {"type":"tabs","tauContract":"0256f72bf503014a7ea32d073aa02da06da7e88c98797870e4d49fa627404693","collabId":"15ff084b-0409-4b3e-a06a-ec90b50fae39","children":[{"type":"tab-pane","tabKey":"db8c6a46-2ded-4dbb-81d0-78225a9fa894","title":"HTML","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"11b47524-00be-439e-8612-b92cc9e1af20","children":[{"type":"code-block","language":"html","uuid":"8d020015-620e-4822-afdd-e22bf914a81a","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"12adbf3d-784a-445d-9f0f-c56df0fb9ee9","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"<div id="container">
 <p>世界这么大，我想去看看</p>
</div>
<button id="btn">删除元素</button>","collabId":"735ab5f2-288a-4e95-8d70-5e1bb9cc39e3","children":[{"type":"formatted","text":""}]}]}]},{"type":"tab-pane","tabKey":"d2a16188-899a-448b-8959-0dc7624d098d","title":"JavaScript","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"e4f1851b-fa06-40f1-9501-eb8c8183b5fd","children":[{"type":"code-block","language":"js","uuid":"2d1ae2e2-e9af-41e2-86df-09c037cf2fe9","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"415b462f-3796-4e3c-a0b2-a449c5700f63","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"const container = document.querySelector('#container');
const observer = new MutationObserver(mutations => {
 console.log(mutations);
});
observer.observe(container, {
 childList: true
});

const btn = document.querySelector('#btn');
btn.addEventListener('click', () => {
 const p = container.querySelector('p');
 if (p) {
 container.removeChild(p);
 } else {
 container.innerHTML = '<p>世界这么大，我想去看看</p>';
 }
});","collabId":"e56e3f24-0172-49f9-8f96-186b8b907fe0","children":[{"type":"formatted","text":""}]}]}]}]} ::: 从视频可以观察到，当 p 标签的删除与新增时，均会触发回调函数的执行。 通过 MutationRecord 对象的 addedNodes 与 removedNodes 属性可以访问到添加的节点以及删除的节点。通过 nextSibling 与 prevSibling 可以获得被删除或新增节点的前后兄弟节点（如果不存在则为 null ）。 const observer = new MutationObserver(mutations => { mutations.forEach(mutation => { console.log(mutation.addedNodes); console.log(mutation.removedNodes); }) }); observer.observe(container, { childList: true }); subtree 需要注意的是，设置 childList 为 true ，只能监听直接子元素的新增与删除，对于更深层次的子元素的变化无法监听。 :::tau-node{type="tabs"} {"type":"tabs","tauContract":"0256f72bf503014a7ea32d073aa02da06da7e88c98797870e4d49fa627404693","collabId":"c2c75201-564e-4895-8080-24caa040e7b1","children":[{"type":"tab-pane","tabKey":"db8c6a46-2ded-4dbb-81d0-78225a9fa894","title":"HTML","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"32aeabbc-12e3-4776-9b06-380d553e32cf","children":[{"type":"code-block","language":"html","uuid":"8d020015-620e-4822-afdd-e22bf914a81a","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"814023da-4a56-4d22-b8e3-b37974d3aea4","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"<div id="container">
 <div id="inner-container">
 <p>世界这么大，我想去看看</p>
 </div>
</div>
<button id="btn">删除/新增</button>","collabId":"fee90498-6535-471d-ae5b-146c0762f913","children":[{"type":"formatted","text":""}]}]}]},{"type":"tab-pane","tabKey":"d2a16188-899a-448b-8959-0dc7624d098d","title":"JavaScript","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"f156741b-38c2-4e1f-944c-11d449514700","children":[{"type":"code-block","language":"js","uuid":"2d1ae2e2-e9af-41e2-86df-09c037cf2fe9","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"3ef0aed0-e320-41e3-9d5f-ecb1313d789d","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"const container = document.querySelector('#container');
const observer = new MutationObserver(mutations => {
 console.log(mutations);
});
observer.observe(container, {
 childList: true
});

const btn = document.querySelector('#btn');
btn.addEventListener('click', () => {
 const innerContainer = document.querySelector('#inner-container');
 const p = innerContainer.querySelector('p');
 if (p) {
 innerContainer.removeChild(p);
 } else {
 innerContainer.innerHTML = '<p>世界这么大，我想去看看</p>';
 }
});","collabId":"21181aec-e5c8-4e2a-9c17-fe129b7ff81e","children":[{"type":"formatted","text":""}]}]}]}]} ::: 相比于上例，在 p 标签与 container 之间添加了一个 inner-container 元素，我们还是监听 container 元素，点击按钮时对 p 标签进行移除或者添加。 因为只能监听直接子元素，而 p 标签并不是 container 的 直接子元素，所以 p 标签的删除与新增无法被监听到，所以回调函数不会被执行，控制台不会有任何的输出。 那有没有办法进行深层次的监听呢？答案是有，需要配合 subtree 属性。除了需要指定 childList 为 true 以外还需要指定 subtree 为 true 。 :::tau-node{type="tabs"} {"type":"tabs","tauContract":"0256f72bf503014a7ea32d073aa02da06da7e88c98797870e4d49fa627404693","collabId":"4628f1eb-b2a2-4348-8ec6-9bb0f4ce676a","children":[{"type":"tab-pane","tabKey":"db8c6a46-2ded-4dbb-81d0-78225a9fa894","title":"HTML","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"c2dc12b6-a039-4e83-a249-c585ca8685ae","children":[{"type":"code-block","language":"html","uuid":"8d020015-620e-4822-afdd-e22bf914a81a","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"25c45983-6592-44a0-907b-f8bc5ab1cc20","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"<div id="container">
 <div id="inner-container">
 <p>世界这么大，我想去看看</p>
 </div>
</div>
<button id="btn">删除/新增</button>","collabId":"c04fe8c4-2ec5-4640-bb4a-9af1fc18856a","children":[{"type":"formatted","text":""}]}]}]},{"type":"tab-pane","tabKey":"d2a16188-899a-448b-8959-0dc7624d098d","title":"JavaScript","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"54541bd6-194c-4135-b877-8aac7c613109","children":[{"type":"code-block","language":"js","uuid":"2d1ae2e2-e9af-41e2-86df-09c037cf2fe9","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"a7d2e168-b41f-4a92-9f30-563992b57d3c","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"const container = document.querySelector('#container');
const observer = new MutationObserver(mutations => {
 console.log(mutations);
});
observer.observe(container, {
 childList: true,
 subtree: true
});

const btn = document.querySelector('#btn');
btn.addEventListener('click', () => {
 const innerContainer = document.querySelector('#inner-container');
 const p = innerContainer.querySelector('p');
 if (p) {
 innerContainer.removeChild(p);
 } else {
 innerContainer.innerHTML = '<p>世界这么大，我想去看看</p>';
 }
});","collabId":"49173734-786f-4f99-bdcc-0b9eb1455e1c","children":[{"type":"formatted","text":""}]}]}]}]} ::: 通过 attributes 来监听属性的变化 attributes 当设置 attributes 属性为 true 时，就可以监听到属性的变化，包括自定义属性。 :::tau-node{type="tabs"} {"type":"tabs","tauContract":"0256f72bf503014a7ea32d073aa02da06da7e88c98797870e4d49fa627404693","collabId":"3ea1bb89-c8a2-4d4f-93a3-fad79117cc71","children":[{"type":"tab-pane","tabKey":"db8c6a46-2ded-4dbb-81d0-78225a9fa894","title":"HTML","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"6e077227-46f8-4008-98d7-e977fac00391","children":[{"type":"code-block","language":"html","uuid":"8d020015-620e-4822-afdd-e22bf914a81a","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"a308d3d8-1cd7-402d-9af7-d7de2d15f654","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"<div id="container" class="red">
 <p>世界这么大，我想去看看</p>
</div>
<button id="btn">改变颜色</button>","collabId":"8df89826-21c4-4e57-9b9f-d607ce72b625","children":[{"type":"formatted","text":""}]}]}]},{"type":"tab-pane","tabKey":"d2a16188-899a-448b-8959-0dc7624d098d","title":"CSS","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"37d25346-b28d-4b6b-bc80-d22dfb173ee7","children":[{"type":"code-block","language":"js","uuid":"2d1ae2e2-e9af-41e2-86df-09c037cf2fe9","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"2f208a87-f564-4616-aa0d-83c3336909c4","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":".red {
 color: red;
}
.green {
 color: green;
}","collabId":"7d748727-2c85-4741-83c9-e73558b5d886","children":[{"type":"formatted","text":""}]}]}]},{"type":"tab-pane","tabKey":"39617b78-c39d-4931-93fe-1c23fad9af08","title":"JavaScript","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"75659b65-1bdd-459b-90dc-9079edcd98ee","children":[{"type":"code-block","language":"js","uuid":"dec57271-4b98-4f36-86f8-8c59e97a402b","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"b43ec342-3211-45e1-8ff0-86b52e870df1","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"const container = document.querySelector('#container');
const observer = new MutationObserver(mutations => {
 console.log(mutations);
});
observer.observe(container, {
 attributes: true
});

const btn = document.querySelector('#btn');
btn.addEventListener('click', () => {
 container.classList.toggle('red');
 container.classList.toggle('green');
});","collabId":"683cd6c6-116c-447d-9d66-94f32e1debc9","children":[{"type":"formatted","text":""}]}]}]}]} ::: 在上述代码中，每次点击按钮时，都会对 container 的类名进行改变，交替的添加和删除 red 和 green 类，从而使得文字的样式发生变化。 从视频中的打印结果看，每次我们修改 class 时，回调函数都被执行了，可以看到这次的数组中包含两个元素，一个是删除类的变动，一个是新增类的变动。 可见看到，属性变动对应的 MutationRecord 对象的 type 为 attributes ，通过 attributeName 可以知道什么属性发生了变化。 attributeOldValue 通过设置 attributeOldValue 为 true ，可以知道变动之前的属性值。看一个🌰 :::tau-node{type="tabs"} {"type":"tabs","tauContract":"0256f72bf503014a7ea32d073aa02da06da7e88c98797870e4d49fa627404693","collabId":"85eeb48f-9b7d-42c1-afc7-bd5247f589c0","children":[{"type":"tab-pane","tabKey":"ca6c8f09-4d02-400a-a146-2a0aa7b5476b","title":"HTML","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"4ce731cd-c22c-4519-9a8f-3be215aa9cf7","children":[{"type":"code-block","language":"html","uuid":"d9c78efd-339c-410c-b7b3-ddf3657e17f8","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"1abdb30e-87a9-4388-875b-ca8115a961b2","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"<div id="container" data-text="Hello World"></div>
<button id="btn">改变自定义属性</button>","collabId":"6bdf2206-1c13-4830-a365-a20216911f31","children":[{"type":"formatted","text":""}]}]}]},{"type":"tab-pane","tabKey":"3de8b45a-29ca-4757-958a-819bb4b24bc3","title":"CSS","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"3deb5459-55b4-4b5d-9180-9d09f5dc5a25","children":[{"type":"code-block","language":"css","uuid":"1a5079ef-cac8-4731-ba0b-78f4f0eff12c","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"630518bd-e894-4819-ac93-44738d7d2775","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"#container::before {
 content: attr(data-text);
}","collabId":"42bedaa1-f8f0-4648-a92d-109d1c3ff6f3","children":[{"type":"formatted","text":""}]}]}]},{"type":"tab-pane","tabKey":"20faaffb-ddbe-40fd-a049-f6eb61218c9b","title":"JavaScript","tauContract":"fcfba932818e04e88c2c071bc4f973b1244251a453f417037be7051a453b8f66","collabId":"4f20de16-73a0-4ef8-93f2-32ec3f36bc1d","children":[{"type":"code-block","language":"js","uuid":"ca0e2ccf-5b9f-469c-9e3b-21be223a167d","tauContract":"44e7818805504c164294bff3c403ed0ffed41befee37e5daeb6121e40071bbd6","collabId":"f39ee7df-b316-4c16-a8a8-95a41cf25c66","children":[{"type":"code-step","tauContract":"01b01a08366ee00321331f9860d994321d69c2da591e07b067eb5459c9edf05d","code":"const container = document.querySelector('#container');
const observer = new MutationObserver(mutations => {
 mutations.forEach(mutation => {
 console.log(mutation.oldValue);
 });
});
observer.observe(container, {
 attributes: true,
 attributeOldValue: true
});

const texts = ['Hello World', '你好世界'];
let count = 0;
const btn = document.querySelector('#btn');
btn.addEventListener('click', () => {
 container.dataset.text = texts[++count % 2];
